<?php
require_once __DIR__.'/../../auth/auth_check.php';
require_once __DIR__.'/../../config/database.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $nomor=trim($_POST['nomor_ippkh']??'');$perusahaanId=(int)($_POST['perusahaan_id']??0);
  if($nomor===''||$perusahaanId<1){$error='Nomor IPPKH dan perusahaan wajib diisi.';}else{
    $st=$pdo->prepare('INSERT INTO ippkh (perusahaan_id,nomor_ippkh,tanggal_penerbitan,kegunaan_izin,luas_kawasan,provinsi,status_izin) VALUES (?,?,?,?,?,?,?)');
    $st->execute([$perusahaanId,$nomor,$_POST['tanggal_penerbitan']?:null,$_POST['kegunaan_izin']??'',(float)($_POST['luas_kawasan']??0),$_POST['provinsi']??'',$_POST['status_izin']??'Aktif']);
    header('Location: index.php');exit;
  }
}
$perusahaan=$pdo->query('SELECT id,nama_perusahaan FROM perusahaan ORDER BY nama_perusahaan')->fetchAll();
$rows=$pdo->query('SELECT i.*,p.nama_perusahaan FROM ippkh i JOIN perusahaan p ON p.id=i.perusahaan_id ORDER BY i.created_at DESC')->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detail IPPKH | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Master Izin</p><h1>Detail IPPKH</h1></div></div><div class="row g-3"><div class="col-lg-4"><div class="panel p-3"><h2 class="fs-6">Tambah IPPKH</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><form method="post" class="vstack gap-2"><select name="perusahaan_id" class="form-select" required><option value="">Pilih perusahaan</option><?php foreach($perusahaan as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nama_perusahaan'])?></option><?php endforeach?></select><input class="form-control" name="nomor_ippkh" placeholder="Nomor IPPKH" required><input type="date" class="form-control" name="tanggal_penerbitan"><textarea class="form-control" name="kegunaan_izin" rows="2" placeholder="Kegunaan izin"></textarea><input type="number" step="0.01" class="form-control" name="luas_kawasan" placeholder="Luas kawasan (Ha)"><input class="form-control" name="provinsi" placeholder="Provinsi"><select class="form-select" name="status_izin"><option>Aktif</option><option>Dicabut</option><option>Berakhir</option></select><button class="btn btn-orange">Simpan</button></form></div></div><div class="col-lg-8"><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>Nomor IPPKH</th><th>Perusahaan</th><th>Tanggal</th><th>Luas</th><th>Provinsi</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nomor_ippkh'])?></td><td><?=htmlspecialchars($r['nama_perusahaan'])?></td><td><?=htmlspecialchars($r['tanggal_penerbitan']?date('d/m/Y',strtotime($r['tanggal_penerbitan'])):'-')?></td><td><?=number_format((float)$r['luas_kawasan'],2,',','.')?> Ha</td><td><?=htmlspecialchars($r['provinsi'])?></td><td><?=htmlspecialchars($r['status_izin'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center py-4">Belum ada IPPKH.</td></tr><?php endif?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
